func TestClause11225TypedDistribution(t *testing.T) {
	psiCheckVectors(t, psi13Codec, psi13Vectors)
	psiCheckMandatoryCuts(t, psi13Codec, psi13Vectors[0])
}
func FuzzPSI13Distribution(f *testing.F) { psiFuzz(f, psi13Codec, psi13Vectors[len(psi13Vectors)-1]) }
